// spec: specs/search-filters.md (3.1) · кейс: .qa/tests/search-filters/FILTER-COMBO-01.md
// seed: tests/seed.spec.ts (гость) · прод, только чтение. Категория и город — самые частые в каталоге сайта,
// границы цены — из цен базовой выдачи; ожидаемо = базовая выдача (без цены) ∩ диапазон цены.
import { test, expect } from '@playwright/test';
import {
  prepareReadOnly, captureCatalog, openPage, openFilter, fields, enter, applyFilter, resultIds, idsInRange, expectResults,
  pricePoints, Biz, LOAD,
} from './search-filters.helpers';

test.use({ serviceWorkers: 'block' });

function mostFrequent(catalog: Biz[], key: 'category' | 'city'): string {
  const m = new Map<string, number>();
  for (const b of catalog) if (b[key]) m.set(b[key]!, (m.get(b[key]!) || 0) + 1);
  const top = [...m.entries()].sort((a, b) => b[1] - a[1])[0];
  if (!top) throw new Error(`В каталоге нет поля ${key} — данные сайта`);
  return top[0];
}

type Combo = { name: string; params: (c: Biz[]) => Record<string, string>; bounds: 'max' | 'min' | 'both' };
const COMBOS: Combo[] = [
  { name: 'категория + макс', params: (c) => ({ category: mostFrequent(c, 'category') }), bounds: 'max' },
  { name: 'город + мин', params: (c) => ({ city: mostFrequent(c, 'city') }), bounds: 'min' },
  { name: 'текст «קפה» + макс', params: () => ({ q: 'קפה' }), bounds: 'max' },
  { name: 'категория + текст «קפה» + мин и макс', params: (c) => ({ category: mostFrequent(c, 'category'), q: 'קפה' }), bounds: 'both' },
];

test.describe('Фильтры поиска — цена вместе с категорией, городом и текстом', () => {
  for (const dev of [{ tag: '@desktop', popup: false }, { tag: '@android', popup: true }]) {
    for (const combo of COMBOS) {
      test(`${combo.name}: выдача = базовая выдача ∩ диапазон цены #b4b8c9 ${dev.tag} @prod-safe`, async ({ page, context }) => {
        await prepareReadOnly(context);
        const catalog = captureCatalog(page);
        await openPage(page, '/search');
        const all = await catalog();

        const params = combo.params(all);
        const qs = new URLSearchParams(params).toString();
        await openPage(page, `/search?${qs}`);
        const base = await resultIds(page);
        expect(base.length, `базовая выдача ${qs} не пустая — иначе данные сайта`).toBeGreaterThan(0);

        const p = pricePoints(all, base);
        const min = combo.bounds === 'max' ? null : combo.bounds === 'min' ? p.mid : p.low;
        const max = combo.bounds === 'min' ? null : combo.bounds === 'max' ? p.mid : p.high;
        const expected = idsInRange(all, min ?? 0, max, base);
        expect(expected.length, 'в пересечении есть объявления').toBeGreaterThan(0);

        const scope = await openFilter(page, dev.popup);
        if (min !== null) await enter(fields(scope).min, min, 'type');
        if (max !== null) await enter(fields(scope).max, max, 'type');
        await applyFilter(page);
        await page.waitForURL(
          (u) =>
            Object.entries(params).every(([k, v]) => u.searchParams.get(k) === v) &&
            (min === null || u.searchParams.get('minPrice') === String(min)) &&
            (max === null || u.searchParams.get('maxPrice') === String(max)),
          LOAD,
        );
        await expectResults(page, expected, `${qs} + цена [${min ?? '—'}..${max ?? '—'}]`);
      });
    }
  }
});
